    philosophy: 'Les trois caractéristiques (tilakkhaṇa) sont les verres à travers lesquels la sagesse bouddhiste voit la réalité. Anicca, dukkha, anattā : impermanence, insatisfaction, non-soi. Voir clairement ces trois traits libère des principales sources de souffrance : l\'attachement à la permanence, à la satisfaction durable, et à un soi fixe.',
    philosophyAuthor: 'Ajahn Chah',
    theme: 'Anicca',
    sourceType: 'Samyutta Nikaya',
