    id: 'card-036',
    pali: 'Mātā yathā niyaṃ puttam āyusā ekaputtamanurakkhe — evampi sabbabhūtesu mānasaṃ bhāvaye aparimāṇaṃ.',
    source: 'Sutta Nipata 1:8 — Metta Sutta',
    french: 'Comme une mère protège son fils unique de sa propre vie — qu\'on cultive envers tous les êtres une pensée illimitée.',
    philosophy: 'Le Metta Sutta est la source de la méditation de bienveillance aimante. La métaphore de la mère qui protège son enfant unique avec sa propre vie est la mesure d\'amour proposée. Non un amour conditionnel ou limité — mais un amour sans frontières, qui s\'étend à tous les êtres, visibles et invisibles, proches et lointains.',
