    french: 'Il demeure contemplant le corps dans le corps — ardent, clairement conscient, attentif.',
    philosophy: 'Le Satipaṭṭhāna Sutta est la carte fondamentale de la méditation. Le corps est le premier champ d\'observation : la respiration, les postures, les sensations. Cette observation directe, sans jugement ni réaction, développe une connaissance expérientielle qui transcende les concepts. Le corps est le portail vers le moment présent.',
