    pali: 'Sammā sankappa — nekkhamma, abyāpāda, avihiṃsā.',
    source: 'Samyutta Nikaya 45:8 — Magga-saṃyutta',
    french: 'La juste intention comporte trois aspects : le renoncement, la non-malveillance, la non-violence.',
    philosophy: 'La sammā saṅkappa — la juste intention ou la juste résolution — est le pivot entre la sagesse (vision juste) et la pratique éthique. Le renoncement (nekkhamma) n\'est pas un rejet du monde mais une non-dépendance vis-à-vis des plaisirs sensoriels. La non-malveillance (abyāpāda) est l\'absence active d\'hostilité, le choix délibéré de la bienveillance. La non-violence (avihiṃsā) étend cette bienveillance à tous les êtres. Ces trois intentions ensemble transforment graduellement la structure motivationnelle de toute la vie.',
