    pali: 'Ānāpānassatismiṃ, bhikkhave, samāhite citte, pajānāti yathābhūtaṃ.',
    source: 'Majjhima Nikaya 118:15 — Ānāpānasati Sutta',
    french: 'Par l\'esprit unifié dans la pleine conscience de la respiration, il connaît tel que c\'est.',
