    french: 'Tout ce qui est ressenti est dans la souffrance.',
    philosophy: 'Cette déclaration radicale de la bhikkhunī Dhammadinnā dans la Cūḷavedalla Sutta exprime le troisième sens de dukkha : l\'insatisfaction inhérente aux conditions changeantes. Même les plaisirs les plus raffinés portent en eux le germe de la souffrance par leur impermanence. Ce n\'est pas du pessimisme mais une diagnose précise qui libère de l\'illusion que le bonheur permanent peut être trouvé dans les conditions conditionnées. Reconnaître cette vérité ouvre la porte à la recherche d\'un bien-être qui n\'est pas conditionné.',
