    french: 'L\'attention sage et approfondie est la racine fondamentale de toutes les qualités habiles.',
    philosophy: 'Le yoniso manasikāra — l\'attention juste, profonde et investigatrice — est désigné dans la Sabbāsava Sutta comme la condition fondamentale pour éviter les afflictions et cultiver les qualités qui mènent à la libération. Ce n\'est pas simplement "faire attention" mais approfondir la réflexion de manière à voir les choses telles qu\'elles sont réellement, en accord avec le Dharma. Cette qualité d\'attention transforme chaque expérience en occasion d\'apprentissage et de croissance spirituelle.',
