    pali: 'Ime kho, bhikkhave, cattāro ariyasaccāni — dukkhaṃ, samudayo, nirodho, maggo.',
    source: 'Majjhima Nikaya 141 — Saccavibhaṅga Sutta',
    french: 'Voici, moines, les quatre nobles vérités : la souffrance, son origine, sa cessation, le chemin.',
