    pali: 'Dve ime, bhikkhave, nibbānadhātuyo. Katamā dve? Saupādisesā ca nibbānadhātu, anupādisesā ca nibbānadhātu.',
    source: 'Itivuttaka 44 — Dikanipāta (Les deux éléments du nirvāṇa)',
    french: 'Il y a deux éléments du nirvāṇa : l\'élément nirvāṇa avec résidu, et l\'élément nirvāṇa sans résidu.',
