    source: 'Itivuttaka 50 — Tikanipāta',
    french: 'L\'avidité est non-habile, le non-attachement est habile ; la haine est non-habile, la non-haine est habile ; l\'illusion est non-habile, la non-illusion est habile.',
    philosophy: 'Cette formule présente les trois poisons et leurs antidotes directs. Ce qui est habile (kusala) produit le bien-être et conduit à la libération ; ce qui est non-habile (akusala) produit la souffrance et perpétue l\'enchaînement. Le non-attachement n\'est pas l\'indifférence mais la libération de la dépendance. La non-haine est la bienveillance active. La non-illusion est la sagesse pénétrante. Ces six qualités définissent l\'ensemble du chemin de la transformation spirituelle.',
    philosophyAuthor: 'Thich Nhat Hanh',
    theme: 'Karma',
    sourceType: 'Itivuttaka',
    backgroundImage: 'https://images.pexels.com/photos/1108701/pexels-photo-1108701.jpeg?auto=compress&cs=tinysrgb&w=800',
    premium: true,
