    french: 'D\'une compassion suprême — compatissant envers tous les êtres.',
    philosophy: 'La compassion universelle (sabbabhūtānukampako) est le cœur de l\'idéal du Bouddha tel que le décrit le Sutta Nipāta. Cette compassion ne fait aucune distinction selon les espèces, les races, les conditions ou les mérites. Elle s\'étend à tous les êtres sensibles sans exception, incluant ceux qui causent de la souffrance. C\'est cette qualité sans limite qui distingue la compassion bouddhiste de la simple sympathie humaine ordinaire et en fait un véhicule de transformation universelle.',
