    pali: 'Le vrai amour se nourrit de compréhension — sans compréhension, l\'amour ne peut être vrai.',
    source: 'Thich Nhat Hanh — Enseignements sur l\'Amour, chapitre 1',
    french: 'L\'amour véritable est fait de compréhension — comprendre la souffrance de l\'autre, ses besoins, sa nature profonde. Sans cette compréhension, ce que nous appelons amour peut devenir une forme d\'attachement ou même de domination.',
