    philosophy: 'La pédagogie d\'Ajahn Chah insistait sur la pratique dans la vie quotidienne plutôt que dans des conditions spéciales. Le Dharma n\'est pas une doctrine à étudier mais une réalité à vivre dans chaque souffle, chaque pas, chaque repas. Cette approche enracinée dans le concret est caractéristique de la tradition forestière thaïe qui voit le monastère et la forêt — avec leurs conditions naturelles difficiles — comme les meilleurs terrain d\'entraînement. La réalité ordinaire est le meilleur des maîtres.',
