    french: 'La douleur physique et émotionnelle est inhérente à l\'existence humaine. La souffrance — la résistance à la douleur, l\'histoire que l\'on se raconte à son sujet — est quelque chose que nous ajoutons et que nous pouvons apprendre à ne plus ajouter.',
