    pali: 'Idha modati pecca modati — Il se réjouit ici, il se réjouit dans l\'au-delà.',
    source: 'Udana 4:1 — Meghiya Sutta',
    french: 'Celui qui a fait le bien se réjouit ici-bas et se réjouit dans l\'au-delà — partout il se réjouit, partout il se délecte de la pureté de ses actes.',
    philosophy: 'La Meghiya Sutta rapporte un enseignement important sur la maturation de la pratique. Meghiya, l\'assistant du Bouddha, désirait partir méditer seul dans une forêt paisible. Le Bouddha lui conseilla d\'attendre en raison de son manque de maturité spirituelle. Quand Meghiya insista et partit, sa méditation échoua. Cette histoire illustre que la beauté du lieu de pratique ne compense pas le manque de fondations intérieures — vertu, amitié spirituelle, effort juste — qui doivent précéder la méditation profonde.',
