    pali: 'Diṭṭhe diṭṭhamattaṃ — Dans ce qui est vu, juste ce qui est vu.',
    source: 'Udana 1:10 — Bāhiya Sutta',
    french: 'Dans ce qui est vu, seulement ce qui est vu. Dans ce qui est entendu, seulement ce qui est entendu. Dans ce qui est senti, seulement ce qui est senti. Dans ce qui est connu, seulement ce qui est connu.',
