    pali: 'Tiṇṇo pāragato thale tiṭṭhati brāhmaṇo — Ayant traversé, il se tient sur la rive ferme.',
    source: 'Udana 8:2 — Pātaligāmiya-vagga',
    french: 'Ayant traversé le courant de la souffrance, il se tient sur la rive — ni emporté ni rejeté, mais librement établi dans la paix.',
    philosophy: 'La métaphore de traverser le courant (ogha) du saṃsāra est récurrente dans le bouddhisme. Les quatre courants — désir sensoriel, désir d\'existence, vues erronées et ignorance — emportent les êtres dans le cycle. "Entrer dans le courant" (sotāpatti) est paradoxalement la première étape de la libération : entrer dans le courant du Dharma, couler vers l\'éveil. Celui qui est parvenu sur l\'autre rive se tient dans la fermeté et la stabilité que nulle tempête ne peut ébranler.',
