    pali: 'Iṅgha passa imaṃ lokaṃ — Regarde ce monde.',
    source: 'Sutta Nipata 4:2 — Ratana Sutta',
    french: 'Regarde ce monde : les êtres aveuglés par l\'ignorance s\'agitent comme des poissons dans une flaque qui se réduit — mais les éveillés traversent sans accroches.',
    philosophy: 'Cette vision du monde comme flaque d\'eau rétrécissante offre une perspective puissante sur l\'urgence de la pratique. La flaque symbolise les conditions favorables à la pratique humaine — conditions précieuses et non garanties. Les êtres qui ne pratiquent pas s\'agitent vainement dans cet espace rétrécissant. Mais ceux qui ont traversé — atteint l\'autre rive grâce à la pratique — sont libres des contraintes de cet espace limité. La rareté des conditions propices est un argument puissant pour ne pas remettre la pratique à plus tard.',
