    pali: 'Yāvañcidaṃ, bhikkhave, sattāvāsā — Les demeures des êtres.',
    source: 'Digha Nikaya 33 — Saṅgīti Sutta',
    french: 'Il y a neuf demeures des êtres — depuis les mondes des êtres corporels multiples jusqu\'à la demeure des êtres sans perception — toutes conditionnées, toutes impermanentes.',
    philosophy: 'La description des neuf demeures des êtres dans le Saṅgīti Sutta offre une cosmologie bouddhiste complète, des plans d\'existence les plus grossiers aux plus subtils. Cette carte de l\'existence n\'est pas une mythologie naïve mais une description phénoménologique des états de conscience qui vont de la conscience ordinaire aux états méditatifs les plus profonds. Toutes ces demeures — même les plus élevées — sont conditionnées et impermanentes. Seul le nirvāṇa est inconditionné.',
