    pali: 'Sabbe sattā sukhitā hontu — Que tous les êtres soient heureux.',
    source: 'Sutta Nipata 1:8 — Metta Sutta (verset conclusif)',
    french: 'Que tous les êtres, faibles ou forts, sans exception, longs, grands, moyens, courts, vus ou non vus, proches ou lointains — que tous les êtres soient heureux.',
    philosophy: 'Ce verset de clôture de la Metta Sutta exprime l\'universalité absolue de la bienveillance bouddhiste. Aucun être n\'est exclu — ni par sa taille, ni par sa visibilité, ni par sa proximité géographique ou affective. Cette inclusion totale transcende toutes les limites tribales, nationales ou même biologiques (non seulement les humains mais tous les êtres sensibles). Pratiquer la mettā avec cette universalité progressive est l\'une des pratiques les plus transformatrices et les plus libératrices du bouddhisme.',
    philosophyAuthor: 'Thich Nhat Hanh',
    theme: 'Metta',
    sourceType: 'Sutta Nipata',
