    pali: 'La pleine conscience protège les autres en vous protégeant vous-même.',
    source: 'Thich Nhat Hanh — Le Miracle de la Pleine Conscience, chapitre 7',
    french: 'En prenant soin de vous-même — de votre santé mentale, de votre paix intérieure — vous prenez automatiquement soin des autres, car vous rayonnez ce que vous cultivez.',
    philosophy: 'Thich Nhat Hanh s\'appuie sur une histoire du Canon pāli où l\'acrobate dit à son assistant : "Je me protège en me protégeant moi-même." Le Bouddha commente que c\'est aussi valide : en prenant soin de soi, on prend soin des autres. La santé mentale et émotionnelle est contagieuse — positivement comme négativement. Un praticien qui cultive la paix, la bienveillance et la clarté les répand autour de lui, bénéficiant ainsi à tous ceux avec qui il entre en contact.',
