    philosophy: 'La pédagogie de Thich Nhat Hanh est d\'une grande simplicité accessible : transformer les activités quotidiennes ordinaires en occasions de pratique contemplative. Observer les nuages n\'est pas une activité passive mais une méditation sur l\'impermanence et le non-attachement. Les nuages ne peuvent être saisis — ils se transforment constamment. Apprenons à regarder notre propre vie intérieure avec le même regard ouvert, sans chercher à figer ce qui est par nature fluide.',
