    pali: 'La conscience est comme un jardin — vous pouvez cultiver ce qui vous nourrit.',
    source: 'Thich Nhat Hanh — Transformation et Guérison, chapitre 4',
    french: 'Dans le jardin de la conscience, il y a des graines de joie et de souffrance. Arroser les bonnes graines est la pratique fondamentale de la transformation intérieure.',
    philosophy: 'La métaphore du jardin de la conscience est l\'une des contributions les plus pratiques de Thich Nhat Hanh à la psychologie bouddhiste. Ses enseignements sur le vijñāna (conscience) distinguent les graines de toutes les expériences — positives et négatives — stockées dans la conscience profonde. La pratique consiste à reconnaître ces graines et à choisir délibérément lesquelles arroser. Chaque pensée, chaque action, chaque conversation arrose des graines — de bienveillance ou d\'aversion, de joie ou de ressentiment.',
