    pali: 'Souffrir ensemble — compassion comme fondation de la communauté.',
    source: 'Thich Nhat Hanh — L\'Art de Vivre, chapitre 9',
    french: 'La communauté spirituelle authentique ne fuit pas la souffrance — elle apprend à la traverser ensemble, en se soutenant mutuellement dans la pratique de la compassion.',
    philosophy: 'La Sangha — la communauté de pratique — est le troisième des Trois Joyaux bouddhistes. Thich Nhat Hanh insistait sur l\'importance de la Sangha non comme institution mais comme environnement de soutien et de transformation mutuelle. Traverser la souffrance seul est beaucoup plus difficile. Une communauté de pratique où l\'on peut s\'exprimer honnêtement, être entendu avec compassion et recevoir le soutien du groupe est l\'un des plus précieux cadeaux que le bouddhisme puisse offrir au monde moderne.',
