    pali: 'La joie sans objet — la félicité naturelle de la conscience éveillée.',
    source: 'Thich Nhat Hanh — L\'Art de Vivre, chapitre 4',
    french: 'La joie authentique ne dépend d\'aucune condition externe — elle surgit naturellement quand les nuages des afflictions se dissipent, révélant le soleil toujours présent de la conscience.',
    philosophy: 'Thich Nhat Hanh distingue la joie conditionnée — qui dépend d\'objets, de personnes ou d\'événements externes — de la joie (muditā) qui est une qualité intrinsèque de la conscience éveillée. Cette joie sans objet ne peut être produite par la possession ou l\'accomplissement mais seulement révélée par la dissolution des obstacles mentaux. Elle est le fruit naturel d\'une pratique profonde — pas une récompense mais une révélation de ce qui était toujours là, caché sous les couches de préoccupation et d\'attachement.',
