    pali: 'Dans le zen, il y a un travail à faire — puis il n\'y a plus de travail.',
    source: 'Shunryu Suzuki — Pas Toujours Ainsi, chapitre 4',
    french: 'Au début, méditer demande effort et discipline. Avec la maturité, la méditation devient aussi naturelle que respirer — elle ne demande plus de travail.',
    philosophy: 'Cette description de la progression dans la pratique zen illustre la notion de "wu wei" — l\'action sans effort. Au début, l\'entraînement de l\'esprit est un travail délibéré : revenir à la respiration, remarquer l\'errance du mental, maintenir la posture. Progressivement, à mesure que la pratique s\'intègre, cet effort se dépose dans une qualité naturelle de présence. La méditation cesse d\'être quelque chose que l\'on "fait" pour devenir quelque chose que l\'on "est". C\'est le fruit de l\'entraînement prolongé.',
