    pali: 'Quand vous faites quelque chose, vous devriez vous brûler complètement dedans.',
    source: 'Shunryu Suzuki — Esprit Zen Esprit Neuf, chapitre 8',
    french: 'La pratique authentique requiert une totale implication — ni distraction, ni réserve, ni calcul. Se brûler complètement dans l\'action est l\'expression de la pleine présence.',
