    source: 'Nagarjuna — Ratnāvalī 1:1-10 (La Guirlande de Joyaux)',
    french: 'Ce qui est bienfaisant produit le bonheur temporaire — ce qui est suprêmement bienfaisant produit le bonheur définitif. En bref : renoncer au blâme et cultiver la vertu.',
    philosophy: 'La Ratnāvalī est un traité de sagesse royale que Nagarjuna adressa au roi Sātavāhana. Elle allie la profondeur philosophique mādhyamaka à des conseils pratiques sur la gouvernance éthique. Nagarjuna y distingue le bienfait conventionnel (générosité, vertu ordinaire) du bienfait suprême (réalisation de la vacuité et de la bodhicitta). Les deux niveaux sont nécessaires : sans fondations éthiques conventionnelles, la sagesse philosophique reste stérile ; sans sagesse profonde, la vertu ordinaire reste incomplète.',
