    pali: 'Sukhi hontu, nibbānaṃ sacchikarontu — Qu\'ils soient heureux, qu\'ils réalisent le nirvāṇa.',
    source: 'Anguttara Nikaya 11:16 — Mettā Sutta',
    french: 'Que tous les êtres soient heureux. Que tous les êtres soient libres de la souffrance. Que tous les êtres réalisent le nirvāṇa — la paix la plus profonde.',
    philosophy: 'Cette prière de clôture exprime l\'aspiration fondamentale de la pratique bouddhiste : non seulement sa propre libération mais la libération de tous les êtres. La bodhicitta — le cœur éveillé — est cette orientation vers la libération universelle. Elle transforme la pratique individuelle en pratique universelle : chaque méditation, chaque acte de générosité, chaque moment de pleine conscience contribue au bien-être de tous les êtres. Dans cette vision, il n\'y a pas de libération individuelle séparée — la libération est toujours libération ensemble.',
