    pali: 'Sammādiṭṭhi — La compréhension juste comme fondation de tout le chemin.',
    source: 'Majjhima Nikaya 9 — Sammādiṭṭhi Sutta',
    french: 'La compréhension juste comprend : les habiles et les non-habiles, la nourriture, le dukkha, l\'origine, la cessation et le chemin — et les āsava et leur cessation.',
    philosophy: 'La Sammādiṭṭhi Sutta, enseignée par Sāriputta, offre une définition opérationnelle complète de la "compréhension juste". Elle ne se réduit pas à la compréhension intellectuelle des quatre nobles vérités mais inclut la compréhension de ce qui est habile et non-habile dans la conduite, la compréhension des nutriments de l\'existence et des āsava (afflictions profondes). Cette compréhension juste est à la fois le début et la fin du chemin — elle se développe en spirale à mesure que la pratique s\'approfondit.',
