    pali: 'Saddhā saddhā paññā paññā — Foi et sagesse en équilibre.',
    source: 'Samyutta Nikaya 48:8 — Daṭṭhabbā Sutta',
    french: 'La foi sans sagesse mène à la crédulité ; la sagesse sans foi mène à la sécheresse du cœur. Les deux ensemble mènent à l\'éveil.',
    philosophy: 'Cet enseignement sur l\'équilibre des facultés spirituelles (indriya) est l\'une des leçons pédagogiques les plus précieuses du Canon pāli. La foi (saddhā) sans sagesse peut devenir fanatisme ou superstition. La sagesse sans foi — sans confiance dans la valeur de la pratique et dans la réalité de la libération — peut devenir cynisme ou paralysie. Leur équilibre crée le pratiquant mature : ouvert à la confiance et à l\'émerveillement, tout en maintenant la clarté de la réflexion et de l\'investigation.',
