    pali: 'Tatiyā nibbānadhātu — Le troisième élément du nirvāṇa.',
    source: 'Anguttara Nikaya 3:55 — Nibbāna Sutta',
    french: 'Il y a cette troisième et suprême réalité : le nirvāṇa inconditionné, total refroidissement, total apaisement.',
    philosophy: 'Ce sutta décrit trois niveaux de nirvāṇa selon le degré de purification des āsava. Le troisième — le nirvāṇa total, inconditionné — est la cessation complète de tous les āsava et de tous les attachements. L\'expression "total refroidissement" (parinibbuta) évoque l\'étymologie du nirvāṇa : l\'extinction d\'un feu. Ce feu n\'est pas la conscience elle-même mais les feux des afflictions qui la brûlent. Quand ces feux sont complètement éteints, la conscience reste — fraîche, claire, illimitée, indestructible.',
