    pali: 'Vijjāvimuttiphalaṃ — Le fruit de la libération par la sagesse.',
    source: 'Digha Nikaya 2:98 — Sāmaññaphala Sutta',
    french: 'Par la sagesse et la libération du cœur, il connaît directement : "Ma naissance est épuisée, la vie sainte accomplie, ce qui devait être fait a été fait, il n\'y a plus de retour à cet état."',
    philosophy: 'Cette formule de la réalisation finale est répétée de nombreuses fois dans le Canon pāli comme expression de l\'éveil accompli. Elle décrit non un état de béatitude passive mais une connaissance directe et certaine : savoir que les conditions du cycle saṃsārique sont épuisées, que la pratique est complète, que la libération est définitive. Ce n\'est pas une expérience mystique ineffable mais une connaissance claire et distincte — la plus claire et la plus importante que l\'être humain puisse atteindre.',
