    pali: 'Nibbānasseva santike — Proche du nirvāṇa.',
    source: 'Dhammapada 23:5 — Nāga Vagga',
    french: 'Par une vision imperturbable de la réalité, celui qui a de l\'ardeur, de l\'équanimité et de la pensée claire — celui-là est proche du nirvāṇa.',
    philosophy: 'Ce verset définit les conditions immédiates de l\'approche du nirvāṇa : ardeur (ātāpin), équanimité (upekkha) et pensée claire (sampajañña). Ces trois qualités ne sont pas mystérieuses mais parfaitement pratiques et cultivables. L\'ardeur est la motivation sincère et soutenue. L\'équanimité est la stabilité qui ne s\'effondre ni ne s\'emballe. La pensée claire est la lucidité qui voit les choses telles qu\'elles sont. Ensemble, elles créent les conditions optimales pour que la réalisation du nirvāṇa survienne naturellement.',
