    pali: 'Sīlakkhandhavagga — Le groupe des vertus.',
    source: 'Digha Nikaya 1 — Brahmajāla Sutta (Résumé éthique)',
    french: 'Le Tathāgata est doté de la vertu — dans le petit groupe de vertus, dans le groupe moyen, dans le grand groupe de vertus.',
    philosophy: 'La longue liste des vertus du Bouddha dans la Brahmajāla Sutta n\'est pas une simple hagiographie mais un programme éthique complet organisé en trois niveaux de raffinement. Les petites vertus concernent la conduite extérieure ordinaire. Les vertus médianes concernent les relations sociales. Les grandes vertus concernent la purification subtile des intentions et des vues. Cette progression montre que l\'éthique bouddhiste n\'est pas un code de règles fixes mais un processus de raffinement continu de la sensibilité et de la conscience morale.',
