    pali: 'Vivekaja pītisukha — La joie née de la solitude.',
    source: 'Digha Nikaya 2:78 — Sāmaññaphala Sutta (Premier jhāna)',
    french: 'Retiré des plaisirs sensuels, retiré des états non-habiles, il entre et demeure dans le premier jhāna — accompagné de pensée discursive et d\'investigation, empli de joie et de bonheur nés de la solitude.',
