    source: 'Anguttara Nikaya 6:10 — Ānāpānassati Sutta',
    french: 'Rappelle-toi du Bouddha ainsi : Il est l\'Arahant, l\'Entièrement Éveillé, parfait en connaissance et conduite, le Bienheureux, le Connaisseur des Mondes, le Guide incomparable.',
    philosophy: 'La recollection des qualités du Bouddha (Buddhānussati) est l\'une des pratiques de méditation les plus anciennes et les plus répandues dans le bouddhisme theravāda et mahāyāna. Elle n\'est pas un acte de dévotion aveugle mais une méditation sur les qualités éveillées qui sont potentiellement présentes en chaque être. En contemplant les qualités du Bouddha, on s\'aligne avec ces mêmes qualités en soi-même. Cette pratique développe la confiance (saddhā), l\'inspiration (saṃvega) et la motivation pour la pratique.',
