    french: 'Pénétré de grande compassion pour les êtres, le Bouddha enseigne le Dharma — non pour l\'honneur ou le gain mais pour le bien et le bonheur de tous.',
    philosophy: 'La Bhayabherava Sutta décrit les épreuves de la pratique du Bouddha avant l\'éveil — la peur, les terreurs nocturnes, les doutes — et comment il les a traversées avec ardeur et intégrité. La motivation de sa pratique et de son enseignement n\'était pas personnelle mais universelle : la mahākaruṇā, la grande compassion pour tous les êtres souffrants. Cette motivation altruiste est présentée comme une des conditions essentielles de l\'éveil — et c\'est cette même motivation qui distingue l\'idéal du bodhisattva dans le mahāyāna.',
    philosophyAuthor: 'Matthieu Ricard',
    theme: 'Karuna',
    sourceType: 'Majjhima Nikaya',
    backgroundImage: 'https://images.pexels.com/photos/1108701/pexels-photo-1108701.jpeg?auto=compress&cs=tinysrgb&w=800',
    premium: true,
