    pali: 'Tathatā — La "telléité" — les choses telles qu\'elles sont.',
    source: 'Samyutta Nikaya 12:20 — Paccaya Sutta',
    french: 'Que les Tathāgatas apparaissent ou n\'apparaissent pas, cette loi demeure — les phénomènes surgissent en dépendance de conditions.',
