    pali: 'Santutthi — La contentement comme richesse véritable.',
    source: 'Matthieu Ricard — Bonheur : La Pratique du Bien-Être, chapitre 6',
    french: 'La contentement (santuṭṭhi) n\'est pas la résignation passive — c\'est la sagesse de reconnaître ce qui est suffisant et de ne pas accroître inutilement ses désirs.',
    philosophy: 'Le contentement (santuṭṭhi) est l\'une des vertus les plus fréquemment louées dans le Canon pāli. Matthieu Ricard le présente non comme un idéal ascétique élitiste mais comme une sagesse économique et écologique fondamentale. Dans un monde de surconsommation, la capacité de se sentir satisfait avec moins — non par contrainte mais par compréhension — est à la fois une vertu spirituelle et une nécessité écologique. La contentement libère du hamster wheel du désir consumériste et ouvre l\'espace pour des joies plus profondes.',
