    id: 'card-306',
    pali: 'Bhojanamhi mattaññū — La modération dans la nourriture.',
    source: 'Anguttara Nikaya 3:16 — Padhāna Sutta',
    french: 'Connaître la juste mesure dans la nourriture est une pratique spirituelle — elle cultive la conscience, modère les attachements et soutient la méditation.',
    philosophy: 'La modération dans la nourriture (bhojanamhi mattaññū) est l\'une des qualités recommandées pour le pratiquant dans plusieurs suttas. Elle n\'est pas une mortification du corps mais une pratique de pleine conscience appliquée à l\'alimentation : manger avec attention, savourer chaque bouchée, reconnaître la faim et la satiété, ne pas manger pour l\'émotion. Cette pratique crée la légèreté physique et mentale qui soutient la méditation, et cultive la gratitude pour la nourriture qui sustente la vie.',
