    pali: 'Pamādaratā — Se délecter de la négligence.',
    source: 'Dhammapada 2:3 — Appamāda Vagga',
    french: 'Les fools se délectent de la négligence ; le sage protège la vigilance comme un trésor suprême.',
    philosophy: 'Le contraste entre pamāda (négligence, distraction) et appamāda (vigilance, diligence) court à travers tout le Canon pāli. La négligence n\'est pas simplement l\'oubli momentané mais une orientation générale de la vie vers la superficialité et la fuite de la réalité. Protéger sa vigilance "comme un trésor" implique que cette qualité est précieuse, rare et facilement perdue si l\'on ne la cultive pas activement. Dans le monde moderne de la distraction permanente, cette enseigne est plus pertinente que jamais.',
