    pali: 'Saṃsāra — Le cycle de l\'existence conditionnée.',
    source: 'Samyutta Nikaya 15:1 — Anamatagga-saṃyutta',
    french: 'Sans commencement discernable est ce saṃsāra. On ne peut discerner un premier point aux êtres qui errent et transmigrent, obstrués par l\'ignorance et enchaînés par le désir.',
    philosophy: 'L\'Anamatagga-saṃyutta enseigne que le saṃsāra est "sans commencement discernable" — anamatagga. Cette formule est souvent mal comprise comme affirmant que le saṃsāra est éternel. Mais le sens est plutôt que, depuis notre position dans le cycle, nous ne pouvons pas discerner un commencement. Cette vision est à la fois humiliante (nous sommes en plein milieu d\'un processus immense) et libératrice (si le saṃsāra peut avoir une fin — le nirvāṇa — alors la libération est possible).',
