    pali: 'Vipāka — Le mûrissement du karma.',
    source: 'Anguttara Nikaya 3:99 — Tittha Sutta',
    french: 'Le karma n\'est pas un fatalisme — c\'est une loi de responsabilité. Les actions présentes façonnent l\'avenir, ce qui signifie que l\'avenir est entre nos mains.',
    philosophy: 'La doctrine du vipāka — le mûrissement ou la maturation du karma — est souvent mal comprise comme fatalisme. Matthieu Ricard, Ajahn Chah et d\'autres maîtres contemporains insistent sur sa dimension libératrice : si les actions passées conditionnent le présent mais ne le déterminent pas entièrement, et si les actions présentes façonnent l\'avenir, alors la transformation est toujours possible. Le karma n\'est pas une prison mais une loi de croissance — comme une graine qui devient un arbre selon les conditions qu\'on lui offre.',
