    pali: 'Tisso sikkhā — Les trois entraînements.',
    source: 'Anguttara Nikaya 3:88 — Sikkhattatiya Sutta',
    french: 'Il y a ces trois entraînements : l\'entraînement dans la vertu supérieure, l\'entraînement dans le mental supérieur, l\'entraînement dans la sagesse supérieure.',
    philosophy: 'Les trois sikkhā — sīla, samādhi, paññā — sont la colonne vertébrale de la pratique bouddhiste depuis ses origines. La beauté de cette structure trifacétée est que chacun des trois niveaux soutient et approfondit les deux autres dans une spirale ascendante. La vertu pacifie les conflits qui agitent le mental. La méditation approfondie clarifie la vision. La sagesse transforme la conduite. Et une conduite transformée permet une méditation plus profonde, qui révèle une sagesse plus fine. Ce cercle vertueux est la dynamique même de l\'éveil progressif.',
