    philosophy: 'Les quatre sammappadhāna (efforts corrects) forment un programme éthique et psychologique complet. Prévenir les états non-habiles non encore apparus est de la sagesse préventive. Abandonner ceux qui sont apparus est de la thérapeutique. Développer les états habiles non encore apparus est de la culture spirituelle. Maintenir ceux qui sont apparus est de la persévérance. Ces quatre mouvements représentent l\'ensemble du spectre de la pratique éthique — de la garde des portes de la perception au développement actif des vertus.',
