    french: 'En quoi le monde est-il vide, Seigneur ? Il est vide de soi et de ce qui appartient au soi.',
    philosophy: 'La réponse du Bouddha à Ananda dans la Suñña Sutta est l\'une des affirmations les plus directes de la vacuité dans le Canon pāli. Le monde est "vide" non au sens de nihilisme — les phénomènes existent et ont des effets — mais vide de la nature propre (svabhāva) que nous y projetons. Il n\'y a pas de "soi" fixe dans les phénomènes, pas de substance intrinsèque et permanente. Cette vacuité n\'est pas lugubre mais libératrice : un monde vide de nature propre est un monde où tout est possible, où rien n\'est figé.',
