    pali: 'Hatthidanta — L\'ivoire de l\'éléphant — l\'authenticité dans la pratique.',
    source: 'Majjhima Nikaya 28 — Mahāhatthipadopama Sutta',
    french: 'La pratique de pleine conscience du corps est comme les traces d\'un éléphant — toutes les autres traces y rentrent.',
    philosophy: 'La Mahāhatthipadopama Sutta présente la pleine conscience corporelle comme la pratique fondamentale dans laquelle toutes les autres pratiques s\'intègrent, comme toutes les traces d\'animaux rentrent dans les traces de l\'éléphant — les plus grandes. Cette hiérarchisation des pratiques est utile pour le pratiquant qui cherche une fondation solide : cultiver la présence au corps dans toutes les activités est la base la plus stable pour développer ensuite les autres aspects de la pratique.',
    philosophyAuthor: 'Pema Chödrön',
    theme: 'Sati',
