    id: 'card-319',
    pali: 'Cetovimutti paññāvimutti — Libération du cœur et libération par la sagesse.',
    source: 'Majjhima Nikaya 43 — Mahāvedalla Sutta',
    french: 'La libération du cœur est accomplie par la pratique des brahmavihārā. La libération par la sagesse est accomplie par la vision pénétrante des trois caractères.',
    philosophy: 'La Mahāvedalla Sutta distingue deux formes complémentaires de libération : la cetovimutti (libération du cœur) obtenue par le samādhi et les brahmavihārā, et la paññāvimutti (libération par la sagesse) obtenue par l\'investigation directe de l\'impermanence, de la souffrance et du non-soi. Ces deux voies sont complémentaires et finalement convergentes : une pratique profonde de compassion et d\'équanimité ouvre naturellement à la vision du non-soi ; et la vision du non-soi épanouit naturellement la compassion universelle.',
