    id: 'card-321',
    pali: 'Dutiya-nāgāro — La deuxième cité — la méditation comme refuge.',
    source: 'Samyutta Nikaya 35:247 — Dutiya Nāgaraopama Sutta',
    french: 'Comme une cité frontière bien fortifiée ne peut être prise, ainsi la ville de la sagesse — fortifiée par la pleine conscience, défendue par la vertu — ne peut être conquise par le mal.',
    philosophy: 'La métaphore de la cité fortifiée illustre la relation entre les différentes pratiques spirituelles comme système de défense intégré. La pleine conscience est les remparts qui permettent de voir ce qui s\'approche avant qu\'il ne soit trop tard. La vertu est la discipline de la garnison. La sagesse est le commandant qui prend les bonnes décisions. La méditation est l\'entraînement de l\'armée entière. Ensemble, ces pratiques créent une forteresse intérieure que les afflictions ne peuvent pénétrer facilement.',
