    id: 'card-322',
    pali: 'Opanayika — Invitant à venir vérifier soi-même.',
    source: 'Anguttara Nikaya 3:65 — Kālāma Sutta',
    french: 'Ne pas accepter des choses simplement parce qu\'elles viennent d\'une autorité, d\'une tradition ou d\'un maître respecté — vérifier par soi-même si elles sont habiles ou non-habiles.',
    philosophy: 'Le célèbre Kālāma Sutta est souvent présenté comme la "charte de la liberté intellectuelle bouddhiste". Le Bouddha encourage les Kālāmas à ne pas accepter ses enseignements sur la seule base de sa réputation ou de la tradition, mais à les tester dans leur propre expérience. Quand on voit par soi-même que quelque chose conduit au bien-être et à la diminution de la souffrance, on peut l\'adopter. Cette invitation à la vérification expérimentale est à la fois une position épistémique profonde et une manifestation de respect pour l\'intelligence des élèves.',
