    pali: 'Karuṇā-bhāvanā — La méditation de compassion.',
    source: 'Majjhima Nikaya 21 — Kakacūpama Sutta',
    french: 'Même si des bandits vous coupaient membre par membre avec une scie à deux poignées, celui d\'entre vous qui aurait de la haine dans son cœur ne suivrait pas mon enseignement.',
    philosophy: 'La Kakacūpama Sutta (Le Discours de la Scie) contient l\'un des enseignements les plus exigeants sur la compassion dans tout le Canon pāli. Le Bouddha demande à ses moines de maintenir la bienveillance même face aux pires atrocités. Cette demande n\'est pas du masochisme mais une description des limites et de la profondeur de la pratique de mettā. Elle indique que la vraie compassion n\'est pas conditionnelle — elle ne dépend pas du comportement de l\'autre. C\'est la méditation de compassion à son niveau le plus profond.',
