    id: 'card-325',
    pali: 'Sotāpatti — L\'entrée dans le courant.',
    source: 'Samyutta Nikaya 55:1 — Sotāpatti-saṃyutta',
    french: 'L\'entrée dans le courant (sotāpatti) est le premier stade de l\'éveil — la réalisation irréversible des trois joyaux et la dissolution des trois premiers liens.',
    philosophy: 'Le sotāpanna — "entré dans le courant" — est le premier des quatre stades d\'éveil dans le bouddhisme theravāda. Avec cette réalisation, trois liens sont définitivement dissous : la vue du soi (sakkāyadiṭṭhi), le doute (vicikicchā), et l\'attachement aux rites et rituels (sīlabbataparāmāsa). Le sotāpanna a une confiance inébranlable dans les Trois Joyaux et est sur la voie irréversible vers l\'éveil complet. Ce stade est accessible à tout pratiquant sincère et représente un changement fondamental et définitif de perspective.',
    philosophyAuthor: 'Ajahn Chah',
    theme: 'Bodhi',
    sourceType: 'Samyutta Nikaya',
