    pali: 'Nāmarūpa — Nom-et-forme — la structure de l\'expérience.',
    source: 'Digha Nikaya 15:2 — Mahānidāna Sutta',
    french: 'Nāmarūpa — nom-et-forme — désigne la structure complète de l\'expérience : la dimension mentale (nom) et la dimension matérielle (forme) qui ensemble constituent toute phénoménologie.',
    philosophy: 'Le concept de nāmarūpa est l\'une des plus importantes contributions analytiques du Bouddha à la compréhension de l\'expérience. Il montre que toute expérience est bi-dimensionnelle : une dimension matérielle-sensorielle (rūpa) et une dimension mentale-conceptuelle (nāma). Cette dualité n\'est pas une division mais une distinction analytique dans ce qui est en réalité un processus unifié. Comprendre cette structure aide à voir comment les deux dimensions s\'alimentent mutuellement et comment les attachements se forment à leur intersection.',
