    source: 'Sutta Nipata 1:8 — Metta Sutta',
    french: 'Comme une mère protégerait son fils unique de sa vie même — de même, que l\'on cultive un amour sans limites pour tous les êtres.',
    philosophy: 'La métaphore de l\'amour maternel dans la Metta Sutta est particulièrement puissante. L\'amour d\'une mère pour son enfant unique est peut-être l\'expression la plus intense d\'amour dans l\'expérience humaine ordinaire — absolu, sans réserve, prêt au sacrifice. Le Bouddha invite à cultiver cette même qualité d\'amour mais de façon illimitée, pour tous les êtres sans exception. Cette expansion progressive de l\'amour maternel particulier vers un amour universel est le mouvement de la pratique de mettā bhāvanā.',
