    pali: 'Suññatā vipassanā — La méditation de la vacuité.',
    source: 'Majjhima Nikaya 121 — Cūḷasuññata Sutta',
    french: 'Par la pratique progressive de la vacuité — vacuité de village, de forêt, de terre, d\'espace, de conscience — on approche la vacuité sans fluctuation du nirvāṇa.',
    philosophy: 'La Cūḷasuññata Sutta présente une méthode de méditation progressive sur la vacuité. En commençant par observer l\'absence de village dans un endroit vide, puis de forêt dans un endroit différent, le pratiquant entraîne son esprit à percevoir la vacuité comme une réalité concrète et non comme une abstraction philosophique. Cette progression culminant dans "la vacuité immutable, sans fluctuation" — le nirvāṇa — montre que la vacuité est accessible progressivement dans la pratique méditative régulière.',
