    pali: 'Yaṃ kiñci samudayadhammaṃ — Tout ce qui a une origine a une cessation.',
    source: 'Samyutta Nikaya 56:11 — Dhammacakkappavattana Sutta',
    french: 'Tout ce qui a une nature de surgissement a une nature de cessation — c\'est en réalisant cette vérité fondamentale que Kondañña vit clairement.',
