    pali: 'Nibbāna paramaṃ sukhaṃ — Le nirvāṇa est le bonheur suprême.',
    source: 'Dhammapada 15:15 — Sukha Vagga',
    french: 'Le nirvāṇa est le bonheur suprême — non pas parce qu\'il est agréable aux sens, mais parce qu\'il est la cessation complète de toute insatisfaction.',
    philosophy: 'Le paradoxe du bonheur bouddhiste est que le bonheur suprême (paramaṃ sukhaṃ) est la cessation de la souffrance plutôt que la maximisation du plaisir. Cette vision contre-intuitive repose sur une analyse profonde de la nature du bonheur ordinaire : il est toujours temporaire, toujours susceptible de se transformer en souffrance, toujours dépendant de conditions instables. Le bonheur du nirvāṇa est indestructible parce qu\'il ne dépend d\'aucune condition externe et ne peut donc être détruit par aucune condition externe.',
