    pali: 'Vijjā-caraṇa-sampanna — Parfait en connaissance et en conduite.',
    source: 'Digha Nikaya 3:1 — Sonadaṇḍa Sutta',
    french: 'Le Bouddha est "parfait en connaissance et en conduite" — non pas que la connaissance précède la conduite ou vice-versa, mais que les deux se développent ensemble, chacune renforçant l\'autre.',
    philosophy: 'L\'épithète "vijjā-caraṇa-sampanna" est l\'une des neuf qualités traditionnelles du Bouddha récitées dans la Buddhānussati. Elle souligne l\'unité indissociable de la connaissance (vijjā) et de la conduite (caraṇa) dans la réalisation bouddhiste. Une connaissance sans conduite reste stérile ; une conduite sans connaissance peut être aveugle ou rigide. L\'intégration des deux crée l\'être authentiquement éveillé dont la sagesse s\'exprime naturellement dans chaque action.',
    philosophyAuthor: 'Thich Nhat Hanh',
    theme: 'Bodhi',
