    pali: 'Avijjānīvaraṇā — Voilés par l\'ignorance.',
    source: 'Samyutta Nikaya 14:1 — Dhātu-saṃyutta',
    french: 'Les êtres sont voilés par l\'ignorance — c\'est l\'obscurcissement fondamental qui se trouve à l\'origine de toute souffrance et que la sagesse seule peut dissiper.',
    philosophy: 'L\'avijjā — ignorance ou non-connaissance — est la première condition de la chaîne des douze nidāna, l\'origine ultime de toute souffrance. Cette ignorance n\'est pas l\'absence d\'information factuelle mais la non-compréhension de la nature de la réalité — impermanence, souffrance, non-soi. Dissiper cette ignorance par la sagesse directe est le coeur de la libération. La pratique contemplative bouddhiste est essentiellement un processus de dissipation progressive de cette obscurité fondamentale par la lumière de la pleine conscience et de la vision pénétrante.',
