    pali: 'Dhammacakkhu — L\'oeil du Dharma.',
    source: 'Samyutta Nikaya 56:11 — Dhammacakkappavattana Sutta',
    french: 'L\'oeil du Dharma surgit : "Tout ce qui a une nature de surgissement a une nature de cessation." C\'est la vision directe libératrice.',
    philosophy: 'Le "dhammacakkhu" — l\'oeil du Dharma — surgit quand on réalise directement que tout phénomène composé est impermanent et donc sujet à la cessation. Cette réalisation n\'est pas une conclusion logique mais une perception directe, aussi immédiate que voir une couleur. Elle transforme radicalement la relation à l\'expérience : ce qui semblait permanent et fiable est maintenant vu dans sa fragilité. Paradoxalement, cette vision libère de la peur de la perte car elle révèle que l\'attachement à la permanence était lui-même la source de la peur.',
