    pali: 'Dhammānudhamma-paṭipanna — Pratiquant conformément au Dharma dans le Dharma.',
    source: 'Anguttara Nikaya 4:87 — Anudhamma Sutta',
    french: 'Le moine qui pratique conformément au Dharma dans le Dharma, c\'est-à-dire qui comprend le sens des enseignements dans leur application, est appelé le vrai pratiquant.',
    philosophy: 'L\'expression "dhammānudhamma-paṭipanna" décrit le pratiquant authentique qui n\'applique pas les enseignements mécaniquement mais de façon adaptée et vivante. Comprendre le Dharma "dans le Dharma" signifie saisir l\'esprit derrière la lettre, l\'intention derrière la formule. C\'est la différence entre la récitation des préceptes et leur incarnation vivante dans chaque action. Cette maturité dans la pratique permet de répondre de façon créative et appropriée à chaque situation de la vie.',
