    pali: 'Mahākaruṇā lokānukaṃpī — Par grande compassion, pour le bien du monde.',
    source: 'Digha Nikaya 2:1 — Sāmaññaphala Sutta',
    french: 'Le Bouddha enseigne "pour le bien et le bonheur des dieux et des humains" — motivé par la grande compassion, non par l\'honneur ou le gain.',
