    pali: 'Bojjhaṅga — Les sept facteurs de l\'éveil.',
    source: 'Samyutta Nikaya 46:3 — Sīla Sutta',
    french: 'Les sept bojjhaṅgā — pleine conscience, investigation, énergie, joie, tranquillité, concentration, équanimité — cultivés en équilibre mènent à l\'éveil.',
    philosophy: 'Les sept facteurs d\'éveil (bojjhaṅgā) représentent les qualités qui, quand elles sont présentes ensemble et en équilibre, forment les conditions directes de l\'éveil. Ils ne surgissent pas indépendamment les uns des autres mais en séquence et se soutiennent mutuellement. La pleine conscience (sati) est toujours la première ; elle permet l\'investigation (dhamma-vicaya) qui génère l\'énergie (viriya) ; cette énergie produit la joie (pīti) qui donne la tranquillité (passaddhi) ; la tranquillité permet la concentration (samādhi) ; et le tout culmine dans l\'équanimité (upekkhā) parfaite.',
