    philosophy: 'Cet enseignement sur les huit lokadhamma décrit la condition universelle de l\'expérience humaine : être soumis à des fluctuations continues de fortune et d\'infortune. La réaction ordinaire oscille entre élation et effondrement selon la direction de ces vents. La pratique développe une résilience profonde — non l\'insensibilité mais une stabilité fondamentale qui peut accueillir les deux pôles sans être emportée. L\'esprit "ni ébranlé ni non-ébranlé" est la description poétique de l\'upekkhā accomplie.',
