    source: 'Samyutta Nikaya 22:59 — Anattalakkhaṇa Sutta',
    french: 'En contemplant systématiquement "ceci n\'est pas mien, ceci n\'est pas moi, ceci n\'est pas mon soi" dans chacun des cinq agrégats — la libération devient accessible.',
