    french: 'Les Bouddhas disent que le nirvāṇa est suprême. Vacuité, non-soi, impermanence — ces trois enseignent le chemin. Et le chemin est la libération elle-même quand il est marché avec ardeur, sagesse et compassion.',
    philosophy: 'En guise de clôture de ce recueil de 365 cartes de sagesse, cette carte synthèse porte le message central de toute la tradition bouddhiste : le nirvāṇa — la cessation de la souffrance — est possible, accessible, et le chemin vers lui est clairement balisé. Trois vérités caractérisent la réalité : anicca (impermanence), dukkha (souffrance) et anattā (non-soi). Les comprendre dans l\'expérience directe, c\'est marcher le chemin. Et marcher le chemin avec ardeur, sagesse et compassion, c\'est déjà le nirvāṇa en train de se réaliser, moment après moment, pas après pas, souffle après souffle, dans la vie ordinaire transfigurée par l\'éveil.',
